  /* Helpers */
  function slugFromPath(prefix){
    var m = pathname.match(new RegExp('/' + prefix + '/([^/]+)/'));
    if(!m) return '';
    try{ return decodeURIComponent(m[1]).replace(/-/g,' ').replace(/\b\w/g, function(l){ return l.toUpperCase(); }); } catch(e){ return m[1]; }
